\舞台(
	[
		短語('up' 可選取: ⊤ 名稱: 'up' 位置: 地點(-2m 0m))
		短語('屋企' 可選取: ⊤ 名稱: '屋企' 位置: 地點(2m 0m))
		音樂(
			音軌([1 3 5 8 5 3])
			鍵: (選擇() = 'up' ? 2semitones 0semitones)
		)
	]
)\

\舞台(
	[
		短語('right' 可選取: ⊤ 名稱: 'right' 位置: 地點(-2m 0m))
		短語('錯' 可選取: ⊤ 名稱: '錯' 位置: 地點(2m 0m))
		音樂(
			音軌([1 5 8] 樂器: 樂器.鐘 迴圈: ⊥)
			重播: ∆ 選擇() ? (選擇() = 'right') ⊥
		)
	]
)\

\儲存格: [1 3 5 3]
音樂(
	音軌(
		儲存格
		.加入清單(
			儲存格.轉換(ƒ(n2•#) n2 + 2)
		)
		.加入清單(
			儲存格.反轉咗()
		)
		.加入清單(
			儲存格.轉換(ƒ(n3•#) 8 - n3)
		)
		樂器: 樂器.鋼琴
	)
)\
